// Synthetic KTX2 level metadata, used for allocation guards rather than codec validation.
export function ktxImage(width = 16, height = 16, scheme = 0): Buffer {
	const image = Buffer.alloc(136)
	image.set([171, 75, 84, 88, 32, 50, 48, 187, 13, 10, 26, 10])
	image.writeUInt32LE(37, 12)
	image.writeUInt32LE(1, 16)
	image.writeUInt32LE(width, 20)
	image.writeUInt32LE(height, 24)
	image.writeUInt32LE(1, 36)
	image.writeUInt32LE(1, 40)
	image.writeUInt32LE(scheme, 44)
	image.writeUInt32LE(104, 48)
	image.writeUInt32LE(28, 52)
	image.writeBigUInt64LE(132n, 80)
	image.writeBigUInt64LE(4n, 88)
	image.writeBigUInt64LE(scheme === 1 ? 0n : 4n, 96)
	return image
}
